ROOT = Path(__file__).resolve().parent.parent
def esc(s): return html.escape(str(s),quote=True)
def refs(lesson,prefix=''):
    links=[]
    for ref in lesson['refs']:
        if isinstance(ref,tuple):
            code,pages=ref; file=FILES[code]
            links.append(f'<a href="{prefix}{file}#page={pages.split("-")[0]}">{esc(file)} · p. {pages}</a>')
        else:
            title,url=SOURCES[ref];links.append(f'<a href="{url}" target="_blank" rel="noopener">{esc(title)}</a>')
    return '<div class="source-note"><strong>Base e complementos:</strong> '+' · '.join(links)+'</div>'
NAV=[('index.html','Início'),('guia.html','Trilha'),('documentacao.html','Conteúdos'),('atividades.html','Atividades'),('questoes.html','Questões'),('simulado.html','Simulado'),('laboratorio.html','Laboratório')]
def page(file,title,body,prefix='',active=None):
    active=active or file
    nav=''.join(f'<a href="{prefix}{url}" class="{"active" if url==active else ""}" {"aria-current=\"page\"" if url==active else ""}>{label}</a>' for url,label in NAV)
    source=f'''<!DOCTYPE html>
<html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Estudo de robótica baseado nos PDFs da disciplina: explicações, exercícios comentados e simulados."><meta name="theme-color" content="#152b29"><title>{esc(title)} · Robótica Lab</title><link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}assets/style.css"><script defer src="{prefix}assets/data.js"></script><script defer src="{prefix}assets/engine.js"></script><script defer src="{prefix}assets/app.js"></script></head>
<body data-prefix="{prefix}"><a class="skip" href="#main">Pular para o conteúdo</a><header class="topbar"><a class="brand" href="{prefix}index.html"><span class="brand-mark">↗</span>robótica<span class="muted">/ lab</span></a><button class="nav-toggle" aria-label="Abrir menu" aria-expanded="false" aria-controls="nav">☰</button><nav class="nav" id="nav" aria-label="Principal">{nav}</nav></header><main id="main">{body}</main><footer><span>Robótica Lab · Material de estudo autoral · UNAERP / Prof. Carlos Formigoni</span><span><a href="{prefix}fontes.html">Fontes e cobertura</a> · <a href="{prefix}revisao.html">Revisão rápida</a> · Estudo offline, progresso local</span></footer></body></html>'''
    p=ROOT/file;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(source,encoding='utf-8')

def card(lesson):
    n=MODULES.index(lesson)+1
    return f'<a class="card" data-module="{lesson["id"]}" href="conteudos/{lesson["id"]}.html"><span class="tag">{esc(lesson["group"])}</span><span class="card-icon">{n:02}</span><h3>{esc(lesson["title"])}</h3><p>{esc(lesson["summary"])}</p><p><strong>Estudar capítulo →</strong></p></a>'

def lesson_html(lesson,prefix='',full=False):
    return f'<article class="{"doc-chapter" if full else "lesson"}" id="{lesson["id"]}"><span class="eyebrow">Capítulo {MODULES.index(lesson)+1:02} · {esc(lesson["group"])}</span><h1>{esc(lesson["title"])}</h1><p class="lead">{esc(lesson["summary"])}</p>{lesson["body"]}<details class="no-print"><summary>Teste sua compreensão: {esc(lesson["recall"])}</summary><div>{esc(lesson["answer"])}</div></details><div class="print-only"><strong>Revisão:</strong> {esc(lesson["recall"])}<br>{esc(lesson["answer"])}</div>{refs(lesson,prefix)}</article>'

