steps=[('Comece pelo contexto',['fundamentos','historia','computacao-ficcao','paradigmas'],'Explique a diferença entre automação, autonomia e teleoperação. Relacione cada marco histórico a uma capacidade.'),('Prepare as ferramentas',['matematica','estrutura','juntas'],'Converta unidades e conte movimentos independentes. Desenhe base, elos, juntas, punho e ferramenta.'),('Escolha e dimensione a mecânica',['configuracoes','workspace','garras','atuadores','transmissoes'],'Justifique arquiteturas e resolva volume, redução e força de preensão.'),('Entenda a eletrônica e o controle',['motores','sensores','encoders','controle','embarcados','potencia','comunicacao'],'Desenhe uma malha, calcule resolução e energia e explique onde entram driver e firmware.'),('Faça o movimento ganhar sentido',['cinematica','jacobiano','desempenho','dinamica','programacao'],'Calcule cinemática planar e separe precisão, repetibilidade e resolução.'),('Integre percepção e aplicação',['visao','navegacao','ia','seguranca','aplicacoes','projeto'],'Conecte sensor, algoritmo e ação e produza uma proposta com requisitos mensuráveis.')]
